# Fonsi Third Place Finder - File Integrity Rebuild
# This script rewrites every file that was manually typed via Notepad,
# using base64-decoded bytes to guarantee no corruption, missing lines,
# or encoding issues. Run this from anywhere - paths are absolute.

$projectRoot = "C:\Users\HP\Projects\Fonsi_Third_Place_Finder"

function Write-FileFromBase64($RelativePath, $Base64Content) {
    $fullPath = Join-Path $projectRoot $RelativePath
    $dir = Split-Path $fullPath -Parent
    if (!(Test-Path $dir)) {
        New-Item -ItemType Directory -Force -Path $dir | Out-Null
    }
    $bytes = [System.Convert]::FromBase64String($Base64Content)
    [System.IO.File]::WriteAllBytes($fullPath, $bytes)
    Write-Host "Written: $RelativePath" -ForegroundColor Green
}


Write-FileFromBase64 "components\\listings\\ListingCard.tsx" ""

Write-FileFromBase64 "components\\listings\\ListingGrid.tsx" ""

Write-FileFromBase64 "components\\listings\\ListingsSection.tsx" ""

Write-FileFromBase64 "components\\listings\\LocationSearch.tsx" ""

Write-FileFromBase64 "lib\\utils\\geo.ts" ""

Write-FileFromBase64 "app\\api\\geocode\\route.ts" ""

Write-FileFromBase64 "app\\api\\listings\\search\\route.ts" ""

Write-FileFromBase64 "app\\page.tsx" ""

Write-FileFromBase64 "types\\listing.ts" ""

Write-FileFromBase64 "lib\\supabase\\client.ts" ""

Write-FileFromBase64 "lib\\supabase\\server.ts" ""

Write-FileFromBase64 "lib\\utils\\dedupe.ts" ""

Write-FileFromBase64 "config\\categories.ts" ""

Write-FileFromBase64 "lib\\api-clients\\openstreetmap.ts" ""

Write-FileFromBase64 "app\\api\\cron\\fetch-events\\route.ts" ""

Write-FileFromBase64 "components\\layout\\Navbar.tsx" ""


Write-Host ""
Write-Host "All files rebuilt successfully. Now run:" -ForegroundColor Cyan
Write-Host "  Remove-Item -Recurse -Force `"$projectRoot\.next`"" -ForegroundColor Yellow
Write-Host "  cd `"$projectRoot`"" -ForegroundColor Yellow
Write-Host "  npm run dev" -ForegroundColor Yellow
